const ids = ["62:85","62:100","62:117","62:125","62:133","62:157","62:186","62:211","62:92","62:96"];
const nodes = await Promise.all(ids.map(id => figma.getNodeByIdAsync(id)));
const byId = new Map(nodes.map((n,i) => [ids[i], n]));
for (let i=0; i<ids.length; i++) {
  if (!nodes[i]) throw new Error("Missing node " + ids[i]);
}
for (const id of ["62:85","62:100","62:92","62:96"]) {
  if (byId.get(id).type !== "SHAPE_WITH_TEXT") throw new Error("Unexpected shape type at " + id);
}
for (const id of ["62:117","62:125","62:133","62:157","62:186","62:211"]) {
  if (byId.get(id).type !== "CONNECTOR") throw new Error("Unexpected connector type at " + id);
}
const textNodes = nodes.filter(n => "text" in n && n.text);
const fonts = new Map();
for (const n of textNodes) {
  for (const segment of n.text.getStyledTextSegments(["fontName"])) {
    const f = segment.fontName;
    fonts.set(f.family + "|" + f.style, f);
  }
}
await Promise.all([...fonts.values()].map(f => figma.loadFontAsync(f)));
const labels = {
  "62:85":"In stay",
  "62:100":"No-show",
  "62:117":"Card authorised",
  "62:125":"Check-in",
  "62:133":"Check-out",
  "62:157":"Guest cancels",
  "62:186":"Guest cancels",
  "62:211":"Missed check-in"
};
for (const [id, value] of Object.entries(labels)) byId.get(id).text.characters = value;
const h = (r,g,b) => ({r:r/255,g:g/255,b:b/255});
const presets = {
  "62:92": {name:"green", fill:h(0x66,0xd5,0x75), stroke:h(0x3e,0x9b,0x4b), text:h(0xff,0xff,0xff)},
  "62:96": {name:"red", fill:h(0xff,0x75,0x56), stroke:h(0xdc,0x30,0x09), text:h(0xff,0xff,0xff)},
  "62:100":{name:"orange", fill:h(0xff,0x9e,0x42), stroke:h(0xeb,0x75,0x00), text:h(0xff,0xff,0xff)}
};
for (const [id, preset] of Object.entries(presets)) {
  const shape = byId.get(id);
  shape.fills = [{type:"SOLID", color:preset.fill}];
  shape.strokes = [{type:"SOLID", color:preset.stroke}];
  shape.text.fills = [{type:"SOLID", color:preset.text}];
}
return {
  mutatedNodeIds: ids,
  updatedLabels: labels,
  endStateColors: {
    Completed: {preset:"green", hex:"#66D575", nodeId:"62:92"},
    Cancelled: {preset:"red", hex:"#FF7556", nodeId:"62:96"},
    "No-show": {preset:"orange", hex:"#FF9E42", nodeId:"62:100"}
  }
};

